/* Chrome, Edge, Safari 브라우저 기본*/
::-webkit-scrollbar {
  width: 7px; /* 스크롤바 너비 */
  height: 8px;
  background: var(--scrollbar-bg-color); /* 스크롤바 배경 */
}

::-webkit-scrollbar-thumb {
  background-color: var(--scrollbar-thumb-color);
  border-radius: 4px;
  cursor:pointer;
}

::-webkit-scrollbar-track {
  background: transparent; /* 트랙 배경 */
}

/* 화살표 제거 (크롬에선 보통 자동 제거됨) */
::-webkit-scrollbar-button {
  display: none !important;
  height: 0 !important;
  width: 0 !important;
  background: transparent !important;
  visibility: hidden !important;
}

/* 특정 div */
.custom-scroll {
  overflow-y: auto;
}

/* Webkit 브라우저용 스크롤바 스타일 */
.custom-scroll::-webkit-scrollbar {
  width: 7px; /* 얇은 스크롤바 */
}

.custom-scroll::-webkit-scrollbar-thumb {
  background-color: var(--scrollbar-thumb-color-02);
  border-radius: 10px;
}

.custom-scroll::-webkit-scrollbar-track {
  background-color: var(--scrollbar-bg-color-02);
}

