html {
  /*width: 100%;*/
  /*height: 100%;*/
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

a {
  color: var(--a-color);
}

h1,
h2,
h3,
h4,
h5,
h6,
p,
ul,
menu,
li,
dl,
dd,
figure,
hr {
  margin: 0;
  padding: 0;
}

ul li,
menu li {
  list-style: none;
}

body {
  padding: 0;
  margin: 0;
  /*font-family: "Roboto", "Roboto Fallback", 'Noto Sans KR', "NotoSansKR", "NotoSansKR Fallback", "Malgun Gothic", "맑은 고딕", helvetica, sans-serif !important;*/
  font-family: 'Noto Sans KR', "NotoSansKR", "NotoSansKR Fallback", "Malgun Gothic", "맑은 고딕", helvetica, sans-serif !important;
  font-style: normal;
  font-weight: 500;
  font-feature-settings: "liga" off, "clig" off;
  font-size: 14px;
  line-height: 1.285714285714286;
    letter-spacing: -0.03em;
  background-color: var(--bg-color-01);
  color: var(--text-color-01);

  /* 숫자 폰트를 고정폭으로 맞출 때 사용 */
  /* font-feature-settings: 'tnum'; */
  /* font-variant-numeric: tabular-nums; */
}

@keyframes fadeDropDown {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

header.header-normal {
    display: flex;
    justify-content: center;
    align-items: start;
    position: fixed;
    top: 0;
    left: 0;
    padding-right: 66px;
    padding-top: 0px;
    width: 100%;
    min-width: calc(var(--min-wide-width-px));
    height: 105px;
    border-bottom: 1px solid var(--white1-border-light2);
    background-color: var(--white1-bg);
    /*background-color: var(--white1-bg-blur);*/
    overflow: visible;
    z-index: var(--z-index-header);
    /*backdrop-filter: blur(16px);*/
    /*-webkit-backdrop-filter: blur(16px);*/
    transition: height 0.16s ease;
}

header.header-normal.min {
    position: fixed;
    top: 0;
    height: 63px;
}


/*
@media (max-width: 1149px) {
  header.header-normal {
    justify-content: flex-start;
  }
} */

header.header-normal .clear-button {
    appearance: none;
    all: unset;
    cursor: pointer;
    display: flex;
    align-items: center;
}

header.header-normal .container {
    /*border-bottom: 1px solid var(--border-color-01);*/
    position: absolute;
    bottom: 0;
    /*width: var(--exclude-lnb-width-px);*/
    width: calc(100% - 65px);
    height: min-content;
    min-width: calc(var(--min-wide-width-px) - 65px);
    max-width: var(--exclude-lnb-width-px);
    /* border: 1px solid transparent; */
    color: var(--text-color-01);
    margin: 0 auto;
}

/* info-area */
header.header-normal .container .info-area {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    padding-left: 10px;
    margin-bottom: 3px;
    margin-top: 0px;
    height: 33px;
}

header.header-normal .container .info-area .left-menu,
header.header-normal .container .info-area .right-menu {
    display: flex;
    position: relative;
}

header.header-normal .container .info-area .left-menu .logo {
    display: flex;
    margin-top:5px;
}

header.header-normal .container .info-area .left-menu .logo a {
    cursor: pointer;
    text-decoration: none;
    display: flex;
    align-items: center;
    justify-content: flex-start;
    gap: 4px;
    color: var(--text-color-01);
    text-align: center;
    font-size: 19px;
    font-style: normal;
    font-weight: 800;
    line-height: 1.068421052631579;
}

header.header-normal .container .multi-search-container {
    position: absolute;
    right: 2px;
    top: 4px;
    width: 378px;
    height: 42px;
    transition: top 0.16s ease, width 0.16s ease;
    z-index: var(--z-index-main-search);
}
/*header.header-normal .container .multi-search-container.min {*/
/*  top: 60px;*/
/*  width: 377px;*/
/*}*/
header.header-normal .container .multi-search-container .multi-search {
    z-index: var(--z-index-main-search);
    display: flex;
    width: 366px;
    height: 42px;
    padding: 8px 16px 8px 19px;
    justify-content: space-between;
    align-items: center;
    flex-shrink: 0;
    border-radius: 38px;
    border: 1px solid var(--border-color-01);
    background-color: var(--bg-color-01);
    transition: width 0.16s ease;
}
header.header-normal .container .multi-search-container .multi-search .help-tooltip {
    position: absolute;
    top: -5px;
    left: -15px;
}
header.header-normal .container .multi-search-container .multi-search .help-tooltip .help-btn {
    width: 26px;
    height: 25px;
    background-image: var(--icon-help);
}
header.header-normal .container .multi-search-container .multi-search .help-tooltip-box {
    position: absolute;
    top: 0;
    left: 0;
    padding: 20px;
    border: 1px solid var(--border-color-01);
    border-radius: 20px;
    animation: fadeDropDown 0.3s ease;
}
.help-tooltip-box {
    width: 430px;
    height: auto;
    background-color: var(--bg-color-01);
}
header.header-normal .container .multi-search-container.min .multi-search .help-tooltip-box {
    width: 328px;
}
.help-tooltip-box .tooltip-title {
    margin-bottom: 14px;
    display: flex;
    align-items: center;
    padding-left: 30px;
    height: 21px;
    background-image: var(--icon-help);
    background-repeat: no-repeat;
    background-size: 21px 21px;
    background-position: 0 0;
}
.help-tooltip-box .tooltip-example {
    margin-top: 14px;
    font-weight: 400;
}
.help-tooltip-box .tooltip-example strong {
    display: block;
    font-weight: 500;
    margin-top: 3px;
}
header.header-normal .container .multi-search-container .multi-search .search-btn {
    width: 20px;
    height: 21px;
    background-image: var(--icon-search);
}
header.header-normal .container .multi-search-container.min .multi-search {
    /*width: 328px;*/
}

header.header-normal .container .multi-search-container .profile-icon {
    position: absolute;
    right: 0;
    top: 0;
    width: 43px;
    height: 43px;
    border-radius: 50%;
    background-color: var(--bg-color-33);
    background-image: var(--icon-profile);
    background-size: 42px;
}

header.header-normal .container .multi-search-container .list-dropdown-popup ul li a {
    color: var(--text-color-12);
    text-decoration: none;
}
header.header-normal .container .multi-search-container .list-dropdown-popup {
    /*left: 354px;*/
    left: auto;
    right: 0;
    transition: left 0.16s ease;
}
header.header-normal .container .multi-search-container.min .list-dropdown-popup {
    left: auto;
    transition: left 0.16s ease;
}

header.header-normal .container .multi-search .left-side {
    display: flex;
    align-items: center;
    gap: 8px;
}

header.header-normal .container .multi-search .left-side {
    width: 100%;
}

header.header-normal .container .multi-search .categoty {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: flex-start;
    font-weight: 600;
    color: var(--text-color-01);
}

header.header-normal .container .icon-angle-down {
    display: block;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    width: 24px;
    height: 24px;
    background-image: var(--icon-angle-down);
}

header.header-normal .container .multi-search .vertical-line {
    width: 1px;
    height: 14px;
    border-left: 1px solid #cdcdcd;
}

header.header-normal .container .multi-search .left-side .search-box{
    /*display: flex;*/
    width: calc(100% - 111px);
}
header.header-normal.min .container .multi-search .left-side .search-box {
    /*display: flex;*/
    width: calc(100% - 111px);
}

header.header-normal .container .multi-search input {
    appearance: none;
    width: 100%;
    border: none;
    outline: none;
    color: var(--text-color-01);
    font-size: 15px;
    font-style: normal;
    background-color: transparent;
}

header.header-normal .container .multi-search input::placeholder{
    color: var(--text-color-03);
}

header.header-normal .container .info-area .left-menu .multi-search .search-button img{
    /* margin-top: 3px; */
}

header.header-normal .container .info-area .right-menu.site-direction dl {
    display: flex;
    align-items: center;
    margin-right: 5px;
}

header.header-normal .container .info-area .right-menu.site-direction dd {
    color: var(--text-color-06);
    position: relative;
    margin: 0 10px;
    font-weight: 400;
}

header.header-normal .container .info-area .right-menu.site-direction dd a{
    color: var(--text-color-06);
    text-decoration: none;
}

header.header-normal .container .info-area .right-menu.site-direction dd + dd::before {
    content: "";
    position: absolute;
    left: -8px;
    top: 50%;
    transform: translateY(-50%);
    width: 1px;
    height: 12px;
    background-color: var(--border-color-05);
}

header.header-normal .container .info-area .right-menu.site-direction .needs-underline:hover{
    text-decoration: underline;
    text-decoration-color: var(--text-color-01);
}

header.header-normal .container .info-area .right-menu.site-direction dl dd.logged-in{
    position: relative;
    display: flex;
    align-items: center;
    padding-right: 0;
}

header.header-normal .container .info-area .right-menu.site-direction dl dd.logged-in .name {
    font-weight: 700;
}

header.header-normal .icon-arrow,
.icon-arrow {
    display: block;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    width: 18px;
    height: 18px;
    transform: rotate(180deg);
    background-image: var(--icon-arrow);
}

.list-dropdown-popup {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    position: absolute;
    top: calc(100% + 12px);
    left: -2px;
    /*display: none;*/
    width: 105px;
    padding: 12px;
    border-radius: 10px;
    border: 1px solid var(--border-color-02);
    background-color: var(--bg-color-01);
    z-index: var(--z-index-list-dropdown-popup);

    opacity: 0;
    visibility: hidden;
    transition: opacity 0.16s ease, visibility 0.16s ease;
    /*pointer-events: none;*/
}
.list-dropdown-popup.show {
    opacity: 1;
    visibility: visible;
    /*pointer-events: auto;*/
}


.list-dropdown-popup#categoryPopup, .list-dropdown-popup#min-categoryPopup{
    left: -12px;
    top: calc(100% + 19px);
}

.list-dropdown-popup ul {
    overflow: visible;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
}

.list-dropdown-popup li{
    color: var(--text-color-18);
    font-size: 13px;
    font-style: normal;
    font-weight: 500;
}

.list-dropdown-popup li.active{
    font-size: 14px;
    font-style: normal;
    font-weight: 700;
    line-height: 1.45;
    color: var(--text-color-18);
}

.list-dropdown-popup li button{
    appearance: none;
    all: unset;
    cursor: pointer;
}

.list-dropdown-popup li:hover{
    text-decoration: underline;
    text-decoration-color: var(--text-color-01);
}

/* menu-area */
header.header-normal .container .menu-area {
    position: relative;
    display: flex;
    margin: 0 0px 0 0px;
    justify-content: space-between;
    align-items: center;
}

header.header-normal .container .menu-area .left-menu menu {
    display: flex;
    gap: 2px;
}

header.header-normal .container .menu-area .left-menu menu li {
    color: var(--text-color-201);
    font-size: 16px;
    font-style: normal;
    font-weight: 500;
    line-height: 1;
    padding: 19px 5px;
    margin: 0px 8px;
    border-bottom: 3px solid transparent;
    transition: border-color 0.3s ease, color 0.3s ease;
}

header.header-normal .container .menu-area .left-menu menu li:hover,header.header-normal .container .menu-area .left-menu menu li.hover,header.header-normal .container .menu-area .left-menu menu li.active {
    /*color: var(--text-color-07);*/
    /*border-bottom: 3px solid var(--text-color-07);*/
    font-weight: 700;
}

header.header-normal .container .menu-area .left-menu menu li.active {
    /*color: var(--text-color-07);*/
    /*border-bottom: 3px solid var(--text-color-07);*/
    /*font-weight: 600;*/
}

header.header-normal .container .menu-area .right-menu {
    opacity: 1;
