.radio-input {
    position: absolute;
    opacity: 0;
}

.radio-visual {
    width: 22px;
    height: 22px;
    position: relative;
}

.radio-visual .radio-outer {
    width: 22px;
    height: 22px;
    background: #b8b8b8;
    border-radius: 9999px;
    position: absolute;
    top: 0;
    left: 0;
}

.radio-visual .radio-inner {
    width: 12px;
    height: 12px;
    background: white;
    border-radius: 9999px;
    position: absolute;
    top: 5px;
    left: 5px;
    opacity: 1;
    transition: opacity 0.2s;
}

.radio-text {
    color: var(--text-color-01);
    font-feature-settings: "liga" off, "clig" off;
    font-size: 16px;
    font-style: normal;
    font-weight: 400;
    line-height: 1.161290322580645;
    word-break: keep-all;
    white-space: nowrap;
}

.radio-input:checked + .radio-visual .radio-outer {
    background: #458dd6;
}

.radio-visual.checked .radio-outer {
    background: #0091DA;
}


.switch-unit {
    padding: 2px;
