main.signup-signin {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
}

main.signup-signin .login-backdrop {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-color: var(--bg-color-01);
    z-index: -1;
}

main.signup-signin .login-form {
    width: 321px;
    height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 17px;
}

main.signup-signin .login-form .form {
    display: block;
    width: 100%;
    padding: 0 0 20px 0;
}

main.signup-signin .login-form .logo {
    height: 64px;
    padding: 19px 22px 54px 22px;
}

main.signup-signin .login-form .logo .icon-logo {
    display: block;
    width: 148px;
    height: 25px;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    background-image: var(--icon-logo);
}

main.signup-signin .login-form .input-container label, main.signup-signin .login-form .input-container input {
    display: block;
}

main.signup-signin .login-form .input-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 23px;
}

main.signup-signin .login-form .input-container .box {
    display: flex;
    flex-direction: column;
    width: 100%;
}

main.signup-signin .login-form .input-container label {
    color: var(--text-color-42);
    font-feature-settings: 'liga' off, 'clig' off;
    font-size: 15px;
    font-style: normal;
    font-weight: 400;
    line-height: 1.60;
    margin-bottom: 8px;
}

main.signup-signin .login-form .input-container input {
    background: var(--bg-color-34);
    border: 1px solid var(--border-color-53);
    color: var(--text-color-23);
    width: 100%;
    /*background-color: var(--bg-color-13);*/
    /*color: var(--text-color-23);*/
    /*border: 1px solid var(--border-color-58);*/
    height: 38px;
    padding: 7px 5px 7px 13px;
    border-radius: 4px;
    font-size: 16px;
    font-style: normal;
    font-weight: 400;
    line-height: 1.714285714285714;
    outline: none;
}

main.signup-signin .login-form .input-container input:focus, main.signup-signin .login-form .input-container input:active, main.signup-signin .login-form .input-container input:hover {
    border-color: var(--text-color-212);
}

main.signup-signin .login-form .input-container input::placeholder {
    color: #CBCAD7;
}

main.signup-signin .login-form .input-container .options {
    position: relative;
}

main.signup-signin .login-form .input-container .options a {
    padding: 5px 9px;
    text-decoration: none;
    font-size: 14px;
    font-style: normal;
    font-weight: 500;
    line-height: normal;
    color: var(--text-color-43);
}

main.signup-signin .login-form .input-container .options a:hover {
    text-decoration: underline;
    text-decoration-color: var(--text-color-43);
}

main.signup-signin .login-form .input-container .options a + a::before {
    content: "";
    position: absolute;
    left: 40%;
    top: 50%;
    transform: translateY(-50%);
    width: 1px;
    height: 12px;
    background-color: var(--border-color-05);
}

main.signup-signin .login-form .sns-direction {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 23px;
    padding-bottom: 29px;
}

main.signup-signin .login-form .sns-direction hr {
    flex: 1;
    border: none;
    opacity: .8;
    border-top: 1px solid #CBCAD7;
    height: 1px;
}

main.signup-signin .login-form .sns-direction p {
    white-space: nowrap;
    color: var(--text-color-43);
    font-size: 14px;
}

main.signup-signin .login-form .button-lists {
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

main.signup-signin .login-form .button-lists button {
    appearance: none;
    all: unset;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 50px;
    border-radius: 25px;
    border: 1px solid #9794AA;
    color: var(--text-color-44);
    font-size: 15px;
    font-style: normal;
    font-weight: 500;
    line-height: normal;
}

main.signup-signin .login-form .button-lists button:focus, main.signup-signin .login-form .button-lists button:active, main.signup-signin .login-form .button-lists button:hover {
    border-color: var(--text-color-01);
}

main.signup-signin .login-form .button-lists button.needs-indent {
    text-indent: -6px;
}

main.signup-signin .login-form .button-lists img {
    width: 30px;
    height: 30px;
    margin-right: 16px;
}

.login-form .copyright {
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;
    text-align: center;
    gap: 10px;
}

.login-form .copyright span {
    color: var(--text-color-15);
    font-size: 13px;
    font-style: normal;
    font-weight: 400;
}

.login-form .copyright span b {
    font-weight: 700;
