.service-request .table td .flex-between {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
}

.service-request .input-button-wrapper {
    display: flex;
    align-items: center;
    justify-content: flex-start;
    gap: 10px;
}

.service-request button.button.basic-1.personal, .service-request button.button.basic-3 {
    width: 168px;
}

.service-request button.button.basic-1.confirm {
    width: 109px;
    height: 38px;
}

.service-request button.button.basic-1.use-all {
    width: 115px;
    height: 38px;
}

.service-request .select {
    width: 500px;
}

.service-request .input {
    width: 345px;
}

.service-request button.button.basic-1.use-all {
    width: 115px;
    height: 38px;
}

.service-request .service-request-illustration {
    position: absolute;
    top: 10px;
    right: 20px;
    width: 300px;
    z-index: var(--z-index-service-request-illustration);
}

.service-request .service-request-illustration img {
    width: 100%;
    height: auto;
    object-fit: contain;
}

.service-request .coupon-radio-wrapper {
    display: flex;
    align-content: center;
    justify-content: flex-start;
    gap: 20px;
    margin-top: 15px;
}

.service-request .coupon-section {
    /*display: none;*/
    flex-direction: column;
    gap: 10px;
    margin-top: 15px;
}

.service-request .saving-benefit.default {
    color: var(--text-color-15);
    font-size: 17px;
    font-weight: 400;
}

.service-request .saving-benefit.blue {
    color: var(--text-color-212);
    font-size: 17px;
    font-weight: 400;
}

.service-request .current-status {
    color: var(--text-color-01);
    font-size: 16px;
    font-weight: 400;
    margin-top: 15px;
}

.service-request .final-payment-price {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-top: 20px;
    margin-bottom: 0px;
    width: 100%;
}

.service-request .final-payment-price .bg-circle-group {
    width: 947px;
    height: 320px;
    background: none;
    position: relative;
    overflow: hidden;
    border-top-left-radius: 129px;
    border-top-right-radius: 20px;
    border-bottom-left-radius: 20px;
    border-bottom-right-radius: 20px;
}

