.payment-done-failed {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 16px;
    margin-top: 4%;
}

.icon-logo.payment-done-failed {
    margin-bottom: 24px;
}

.payment-done-failed .payment-result {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 10px;
    margin-bottom: 20px;
}

.payment-done-failed .payment-result .text-1 {
    color: #0090DA;
    font-size: 20px;
    font-weight: 600;
}

.payment-done-failed .payment-result .text-2 {
    color: var(--text-color-41);
    font-size: 13px;
    font-weight: 400;
}

.payment-done-failed .payment-detail {
    width: 321px;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: center;
    gap: 16px;
}

.payment-done-failed .payment-detail .text {
    color: var(--text-color-01);
    font-size: 17px;
    font-weight: 500;
}

.payment-done-failed .payment-button {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 10px;
    margin-top: 30px;
}

.payment-done-failed .payment-button button.button.basic-1, .payment-done-failed .payment-button button.button.basic-2, .payment-failed .payment-button button.button.basic-2 {
    width: 321px;
