.trial-request .banner {
    width: 100%;
    /*height: 218px;*/
    /*background: #90BEDA;*/
    /*border-radius: 13px;*/
    /*padding: 32px 40px;*/
    /*box-sizing: border-box;*/
    /*display: flex;*/
    /*justify-content: space-between;*/
    /*align-items: stretch;*/
}

.trial-request .banner .content {
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}

.trial-request .banner .content .title {
    font-size: 24px;
    font-weight: 700;
    line-height: 1.491666666666667;
    color: #ffffff;
}

.trial-request .banner .content .title .highlight {
    color: #003A5F;
}

.trial-request .banner .content .description {
    font-size: 18px;
    font-weight: 500;
    line-height: 1.488888888888889;
    color: #ffffff;
}

.trial-request .banner-icon {
    align-self: center;
    display: block;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    width: 200px;
    height: 100%;
    background-image: var(--trial-request-banner-icon);
}

.trial-request .info {
    width: 100%;
    align-self: stretch;
    padding: 53px 0;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    gap: 45px;
    display: inline-flex;
    text-align: center;
}

.trial-request .info .title {
    color: var(--text-color-01);
    font-size: 21px;
    font-weight: 500;
    line-height: 1.333333333333333;
}

.trial-request .info .description {
    color: var(--text-color-02);
    font-size: 18px;
    font-weight: 400;
    line-height: 1.555555555555556;
}

.trial-request .info .button-wrapper {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 20px;
}

.trial-request .info .button-wrapper button.button.basic-1, .trial-request .info .button-wrapper button.button.basic-2, .trial-request .info .button-wrapper button.button.basic-3 {
    width: 150px;
