.total-search .search-filter-wrapper-1 {
    margin: 10px 0px 15px 0;
}

.total-search .search-filter-wrapper-2 {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: flex-start;
    gap: 10px;
    margin-top: 20px;
}

.total-search .search-button-wrapper, .vehicle-search .search-button-wrapper {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 10px;
    margin: 0 0 15px;
    width: 100%;
    position: sticky;
    bottom: 0;
    padding: 20px 0;
    /*background: var(--bg-color-01);*/
    /*border-top: 1px solid var(--border-color-52);*/
    background: radial-gradient(circle at 30% 30%, var(--header-bg-gra-start), var(--header-bg-gra-end));
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
}

.total-search .search-button-wrapper button.button.basic-1, .vehicle-search .search-button-wrapper button.button.basic-1 {
    width: 176px;
}

.total-search .search-button-wrapper button.button.basic-2, .vehicle-search .search-button-wrapper button.button.basic-2 {
    width: 89px;
}

.total-search .search-button-wrapper button.button.basic-3, .vehicle-search .search-button-wrapper button.button.basic-3 {
    width: 93px;
}

.total-search .table.main {
    table-layout: fixed;
}

.total-search .table.main tr th {
    font-size: 15px;
}

.total-search .table.main thead tr {
    height: 0px;
    visibility: collapse;
}

.total-search .table.main thead tr th.th-1 {
    width: 148px;
    font-size: 15px;
}

.total-search .table.main thead tr th.th-2 {
    width: auto;
}

.total-search .table.main td {
    height: 50px;
}

.total-search .table.main td.purpose {
    height: 310px;
    font-size: 15px;
}

.total-search .table.main .td-wrapper {
    display: flex;
    align-items: center;
    gap: 10px;
}

.total-search .table.main td.special-condition {
    /* height: 118px; */
}

.total-search .table.main .td-wrapper.special-condition {
    height: 39px;
}

.total-search .table.main td.purpose {
    padding: 0px;
}

.total-search .table.main td.purpose table.purpose {
    width: 100%;
    table-layout: fixed;
    border-collapse: collapse;
}

.total-search .table.main td.purpose table.purpose .col-fixed {
    width: 151px;
}

.total-search .table.main td.purpose table.purpose .col-auto {
    width: auto;
}

.total-search .table.main td.purpose table.purpose th {
    border: none;
}

.total-search .table.main td.purpose table.purpose td {
    padding-top: 10px;
    border: 1px solid var(--border-color-52);
}

.total-search .table.main td.purpose table.purpose td.no-top-left {
    border-left: 0px;
    border-top: 0px;
}

.total-search .table.main td.purpose table.purpose td.no-top {
    border-top: 0px;
}

.total-search .table.main td.purpose table.purpose td.no-top-right {
    border-right: 0px;
    border-top: 0px;
}

.total-search .table.main td.purpose table.purpose td.no-bottom-right {
    border-right: 0px;
    border-bottom: 0px;
}

.total-search .table.main td.purpose table.purpose td.no-bottom {
    border-bottom: 0px;
}

.total-search .table.main td.purpose table.purpose td.no-bottom-left {
    border-left: 0px;
    border-bottom: 0px;
}

.total-search .table.main td.purpose table.purpose td.no-left {
    border-left: 0px;
}

.total-search .table.main td.purpose table.purpose td.no-right {
    border-right: 0px;
}

.total-search .table.main td.purpose table.purpose .td-wrapper-row {
    display: flex;
    align-items: flex-start;
    justify-content: flex-start;
    height: 100%;
}

.total-search .table.main td.purpose table.purpose .td-wrapper-col {
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 0px;
}

.total-search .table.main .text-1 {
    font-size: 14px;
    font-weight: 500;
    color: var(--text-color-28);
}

.total-search .table.main .select.select-1 {
    width: 165px;
}

.total-search .table.main .select.select-2 {
    width: 90px;
}

.total-search .table.main .select.select-3 {
    width: 210px;
}

.total-search .table.main .select.select-4 {
    width: 119px;
}

.total-search .table.main .select.select-5 {
    width: 141px;
}

.total-search .table.main .select.select-6 {
    width: 94px;
}

.total-search .table.main .select.select-7 {
    width: 99px;
}

.total-search .table.main .select.select-8 {
    width: 155px;
}

.total-search .table.main .select.select-9 {
    width: 137px;
}

.total-search .table.main .input.input-1 {
    width: 134px;
}

.total-search .table.main .input.input-2 {
    width: 232px;
}

.total-search .table.main .input.input-3 {
    width: 124px;
}

.total-search .table.main .input.input-4 {
    width: 167px;
}

.total-search .table.main .checkbox.checkbox-1 {
    width: 141px;
}

.total-search .table.main .checkbox.checkbox-2 {
    width: auto;
    /*width: 131px;*/
