.date-search .calendar-court-wrapper {
    width: 100%;
    height: auto;
    display: flex;
    align-items: flex-start;
    justify-content: flex-start;
}

.date-search .calendar-court-wrapper .calendar {
    width: 485px;
    padding: 10px 8px 23px 8px;
    background: var(--bg-color-01);
    border-radius: 16px;
    display: flex;
    flex-direction: column;
    gap: 7px;
    border: 1px solid var(--white1-border-light2);
}

.date-search .calendar-court-wrapper .calendar .header {
    height: 50px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 7px;
    /* border-bottom: 1px solid var(--border-color-01); */
}

.date-search .calendar-court-wrapper .calendar .header .nav {
    width: 148px;
    height: 14px;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    cursor: pointer;
}

.date-search .calendar-court-wrapper .calendar .header .nav.arrow-left {
    background-image: url("/images/desktop/icon-calendar-arrow-left.svg");
    background-position: right;
}

.date-search .calendar-court-wrapper .calendar .header .nav.arrow-right {
    background-image: url("/images/desktop/icon-calendar-arrow-right.svg");
    background-position: left;
}

.date-search .calendar-court-wrapper .calendar .header .month {
    font-size: 18px;
    font-weight: 700;
    text-align: center;
    color: var(--text-color-01);
}

.date-search .calendar-court-wrapper .calendar .weekdays {
    display: flex;
    width: 100%;
    margin-bottom: 15px;
}

.date-search .calendar-court-wrapper .calendar .weekdays div {
    flex: 1;
    text-align: center;
    font-weight: 600;
    font-size: 14px;
    padding: 7px;
    color: var(--text-color-56);
}

.date-search .calendar-court-wrapper .calendar .weekdays .sunday {
    color: #F53B32;
}

.date-search .calendar-court-wrapper .calendar .weekdays .saturday {
    color: var(--text-color-212);
}

.date-search .calendar-court-wrapper .calendar .dates {
    display: flex;
    flex-wrap: wrap;
}

.date-search .calendar-court-wrapper .calendar .dates .date {
    width: calc(100% / 7);
    height: 59px;
    padding: 7px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    font-size: 14px;
    font-weight: 400;
    color: var(--text-color-56);
    cursor: pointer;
}

.date-search .calendar-court-wrapper .calendar .dates .date div {
    font-weight: 200;
}

.date-search .calendar-court-wrapper .calendar .dates .date.disabled {
    opacity: 0.3;
    cursor: not-allowed;
}

.date-search .calendar-court-wrapper .calendar .dates .date.sunday {
    color: #F53B32;
}

.date-search .calendar-court-wrapper .calendar .dates .date.saturday {
    color: var(--text-color-212);
}

.date-search .calendar-court-wrapper .calendar .dates .date.active {
    /*background-color: #458DD6;*/
    /*color: white;*/
}

.date-search .calendar-court-wrapper .court, .court-search .court-select-wrapper .court-auction-date {
    position: relative;
    flex: 1;
    height: 100%;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: flex-start;
    padding-left: 20px;
}

.date-search .calendar-court-wrapper .court .selected-date {
    width: 100%;
    font-size: 18px;
    font-weight: 600;
    color: var(--text-color-01);
    border-bottom: 1px solid var(--border-color-01);
    padding: 18px 0px 15px 10px;
}

.date-search .calendar-court-wrapper .court .grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    grid-template-rows: repeat(3, auto);
    width: 100%;
    column-gap: 10px;
    margin-top: 10px;
    padding-left: 9px;
}

.date-search .calendar-court-wrapper .court .grid .box {
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 14px 0 13px 10px;
    cursor: pointer;
    line-height: 1;
}

.date-search .calendar-court-wrapper .court .grid .box .label {
    font-size: 15px;
    font-weight: 400;
    color: var(--white1-text-light2);
    white-space: nowrap;
}

.date-search .calendar-court-wrapper .court .grid .box .count {
    font-size: 13px;
    font-weight: 400;
    color: var(--text-color-28);
}

.date-search .calendar-court-wrapper .court .grid .box.active {
    /*background-color: #458DD6;*/
}

.date-search .calendar-court-wrapper .court .grid .box.active .count, .date-search .calendar-court-wrapper .court .grid .box.active .label {
    /*color: #FFFFFF;*/
}

