.court-search .court-select-wrapper {
    width: 100%;
    height: 310px;
    display: flex;
    align-items: center;
    justify-content: flex-start;
    margin-top: 50px;
}

.court-search .court-select-wrapper .court-location {
    width: 565px;
    max-height: 307px;
    overflow-y: auto;
    overflow-x: hidden;
    border: 1px solid var(--border-color-52);
}

.court-search .court-select-wrapper .court-location::-webkit-scrollbar-thumb {
    background-color: #D3D3D3;
    border-radius: 4px;
}

.court-search .court-select-wrapper .court-location::-webkit-scrollbar-track {
    background-color: var(--bg-color-02);
}

.court-search .court-select-wrapper .court-location .table.location {
    table-layout: fixed;
}

.court-search .court-select-wrapper .court-location .table.location th {
    width: 72px;
    height: 61px;
    font-size: 15px;
    font-weight: 600;
    text-align: center;
    color: var(--component-color-01);
    background-color: var(--component-table-bg-color-01);
}

.court-search .court-select-wrapper .court-location .table.location td {
    padding: 8px;
    background: var(--bg-color-01);
    font-size: 16px;
    border: 1px solid var(--border-color-52);
}

.court-search .court-select-wrapper .court-location .table.location td .td-wrapper {
    display: flex;
    align-items: center;
    justify-content: flex-start;
    flex-wrap: wrap;
    gap: 10px;
    cursor: pointer;
}

.court-search .court-select-wrapper .court-location .table.location td .td-wrapper .box {
    border-radius: 8px;
    text-align: center;
    color: var(--text-color-25);
    font-size: 15px;
    font-weight: 600;
    padding: 10px;
}

.court-search .court-select-wrapper .court-location .table.location td .td-wrapper .box.active {
    background-color: #458DD6;
    color: #FFFFFF;
}

.court-search .court-select-wrapper .court-auction-date {
    position: relative;
    display: flex;
    flex-direction: column;
    padding: 0px 10px;
}

.court-search .court-select-wrapper .court-auction-date .selected-location {
    position: absolute;
    top: -45px;
    width: 100%;
    font-size: 18px;
    font-weight: 400;
    color: var(--text-color-01);
    padding: 10px 0px 15px 2px;
}

.court-search .court-select-wrapper .court-auction-date .table-wrapper {
    width: 100%;
    max-height: 308px;
    overflow-y: auto;
    overflow-x: hidden;
    border: 1px solid var(--border-color-52);
}

.court-search .court-select-wrapper .court-auction-date .table-wrapper::-webkit-scrollbar-thumb {
    background-color: #D3D3D3;
    border-radius: 4px;
}

.court-search .court-select-wrapper .court-auction-date .table-wrapper::-webkit-scrollbar-track {
    background-color: var(--bg-color-02);
}

.court-search .court-select-wrapper .court-auction-date .table-wrapper table {
    width: 100%;
    border-collapse: collapse;
    font-size: 15px;
}

.court-search .court-select-wrapper .court-auction-date .table-wrapper table thead th {
    border: 1px solid var(--border-color-52);
    background-color: var(--component-table-bg-color-01);
    color: var(--text-color-28);
    font-size: 15px;
    font-weight: 600;
    padding: 11px 10px;
}

.court-search .court-select-wrapper .court-auction-date .table-wrapper table thead th.order {
    width: 65px;
    height: 50px;
    padding: 11px 0px;
}

.court-search .court-select-wrapper .court-auction-date .table-wrapper table thead th.previous-date {
    width: 159px;
}

.court-search .court-select-wrapper .court-auction-date .table-wrapper table tbody th {
    border: 1px solid var(--border-color-52);
    background: var(--bg-color-01);
    color: var(--text-color-28);
    font-size: 15px;
    font-weight: 600;
    padding: 5px 0px;
}

.court-search .court-select-wrapper .court-auction-date .table-wrapper table tbody td {
    border: 1px solid var(--border-color-52);
    background: var(--bg-color-01);
    color: var(--text-color-28);
    padding: 5px 10px;
    font-size: 15px;
    font-weight: 500;
}

.court-search .court-select-wrapper .court-auction-date .table-wrapper table tbody td:nth-child(2) {
    text-align: center;
}

.court-search .court-select-wrapper .court-auction-date .table-wrapper table tbody td .td-wrapper {
    display: flex;
    align-items: center;
    justify-content: flex-start;
    flex-wrap: wrap;
    gap: 10px;
}

.court-search .court-select-wrapper .court-auction-date .table-wrapper table tbody td .td-wrapper .box {
    padding: 10px;
    border-radius: 8px;
    color: var(--text-color-25);
    cursor: pointer;
}

.court-search .court-select-wrapper .court-auction-date .table-wrapper table tbody td .td-wrapper .box.active {
    background-color: #458DD6;
    color: #FFFFFF;
}

