.total-search .page-subtitle {
    margin-top: 30px;
}

table.select-location {
    margin-bottom: 30px;
    border: 0;
}

table.select-location tr {
    display: grid;
    grid-template-columns: repeat(9, 1fr);
    width: 100%;
}

table.select-location td {
    cursor: pointer;
    text-align: center;
    vertical-align: middle;
    font-size: 14px;
    font-weight: 400;
    padding: 10px 10px;
}

table.select-location td span.location {
    color: var(--text-color-28);
}

table.select-location td span.count {
    color: #0091DA;
    margin-left: 3px;
}

table.select-location td.active {
    background-color: var(--bg-color-33);
}

table.select-location td.active span {
    color: #FFFFFF;
}

.page-subtitle .tag-select-location {
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 8px;
    background: var(--bg-color-11);
    border-radius: 8px;
}

.page-subtitle .tag-select-location span.gray {
    color: var(--text-color-28);
    font-size: 14px;
    font-weight: 600;
}

.page-subtitle .tag-select-location span.blue {
    color: #0091DA;
    font-size: 14px;
    font-weight: 500;
}

.page-subtitle .tag-select-location i {
    width: 16px;
    height: 18px;
    display: block;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    background-image: var(--icon-angle-down-wide);
}

.page-subtitle .icon-right-arrow {
    font-size: 16px;
    color: #0091DA;
    padding: 0px 10px;
