.personal-bid-calendar .calendar-month-picker {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 10px 0px 20px 0px;
    margin: 10px 0px;
    gap: 20px;
}

.personal-bid-calendar .calendar-month-picker .current-month {
    color: var(--text-color-01);
    font-size: 38px;
    font-weight: 600;
}

.personal-bid-calendar .calendar-month-picker .nav {
    width: 20px;
    height: 20px;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    cursor: pointer;
}

.personal-bid-calendar .calendar-month-picker .nav.arrow-left {
    background-image: url("/images/desktop/icon-calendar-arrow-left.svg");
}

.personal-bid-calendar .calendar-month-picker .nav.arrow-right {
    background-image: url("/images/desktop/icon-calendar-arrow-right.svg");
}

.personal-bid-calendar .calendar-filter-print {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 10px;
}

.personal-bid-calendar .calendar-filter-print .filter-checkbox {
    display: flex;
    align-items: center;
    justify-content: flex-start;
    gap: 15px;
}

.personal-bid-calendar .calendar-filter-print .print-button {
    display: flex;
    align-items: center;
    justify-content: flex-start;
    gap: 10px;
}

.personal-bid-calendar .calendar {
    display: grid;
    grid-template-columns: 35px repeat(5, 1fr) 35px;
    border: 1px solid var(--border-color-52);
; border-top: 3px solid #458DD6;
    width: 100%;
}

.personal-bid-calendar .calendar .calendar-header {
    background: var(--component-table-bg-color-01);
    color: var(--text-color-49);
    font-size: 15px;
    font-weight: 600;
    text-align: center;
    padding: 10px 0;
    border: 1px solid var(--border-color-52);
; }

.personal-bid-calendar .calendar .day-cell {
    min-height: 100px;
    padding: 5px 10px 10px 10px;
    outline: 1px solid var(--border-color-52);
; background: var(--bg-color-01);
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: flex-start;
    font-size: 15px;
    gap: 10px;
}

.personal-bid-calendar .calendar .day-cell .day {
    color: var(--text-color-49);
    font-weight: 600;
}

.personal-bid-calendar .calendar .calendar-header.sunday, .personal-bid-calendar .calendar .day-cell .day.sunday {
    color: #F53B32;
}

.personal-bid-calendar .calendar .calendar-header.saturday, .personal-bid-calendar .calendar .day-cell .day.saturday {
    color: #458DD6;
}

.personal-bid-calendar .calendar .day-cell .calendar-card {
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: flex-start;
    border-radius: 7px;
    border: 1px solid var(--border-color-52);
    overflow: hidden;
    max-width: 197px;
}

.personal-bid-calendar .calendar .day-cell .calendar-card .card-header {
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: flex-start;
    gap: 2px;
    background: var(--component-table-bg-color-01);
    padding: 5px;
}

.personal-bid-calendar .calendar .day-cell .calendar-card .card-header .title {
    color: var(--text-color-01);
    font-size: 15px;
    font-weight: 500;
}

.personal-bid-calendar .calendar .day-cell .calendar-card .card-header .case-number {
