.map-search .map-container {
    width: calc(100vw - 75px);
    display: flex;
    height: 810px;
}

.map-search .map-container .left-side {
    position: relative;
    width: 390px;
    overflow: hidden;
    padding-top: 15px;
}

.map-search .map-container .left-side .search-container {
    display: flex;
    flex-direction: column;
    gap: 20px;
    padding: 0 13px;
}

.map-search .map-container .left-side .search-container .title {
    color: var(--text-color-203);
    font-size: 15px;
    font-style: normal;
    font-weight: 500;
    line-height: 1;
    padding: 4px 0px 5px 0px;
    margin-bottom: 4px;
}

.map-search .map-container .left-side .search-container .route-search-wrap {
    display: flex;
    flex-direction: row;
    gap: 10px;
    align-items: center;
}

.map-search .map-container .left-side .search-container .route-search-wrap .route-search {
    position: relative;
    flex: 1;
}

.map-search .map-container .toggle-group-list-size-btn {
    position: relative;
    width: 33px;
    height: 33px;
    cursor: pointer;
}

.map-search .map-container .toggle-group-list-size-btn-wrap {
    display: flex;
    background-color: var(--bg-color-01);
    border: none;
    box-shadow: 0px 1px 8px var(--bg-color-07);
    border-radius: 50%;
    padding: 2px;
    align-items: center;
    flex-shrink: 0;
}

.map-search .map-container .left-side .route-search .input-field {
    padding: 10px 63px 10px 10px;
    height: 51px;
    border-radius: 10px;
    border: 1px solid #DCDDDF;
    background: var(--bg-color-01);
}

.map-search .map-container .left-side .route-search .input-field:focus {
    border-color: #09AA5C;
}

.map-search .map-container .left-side .route-search .input-field::placeholder {
    color: #979AA0;
}

.map-search .map-container .left-side .route-search button {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    right: 10px;
    border-radius: 7px;
    background: var(--bg-color-30);
    padding: 8px 10px;
    color: #FFF;
    font-size: 16px;
    font-style: normal;
    font-weight: 600;
    line-height: 0.93;
}

.map-search .map-container .left-side .search-container .group-result {
    display: flex;
    gap: 10px;
    align-items: center;
    justify-content: flex-start;
    color: var(--text-color-203);
    font-size: 16px;
    font-style: normal;
    font-weight: 500;
    line-height: 1;
}

.map-search .map-container .left-side .search-container .group-result button {
    border-radius: 12px;
    border: 1px solid #E2E2E2;
    background: var(--bg-color-05);
    padding: 8px 7px;
    /* width: 24px; */
    /* height: 24px; */
}

.map-search .map-container .left-side .search-container .group-result button .icon.icon-arrow-left-thin {
    display: block;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    width: 10px;
    height: 9px;
    background-image: var(--icon-arrow-left-thin);
}

.map-search .map-container .left-side .filter-wrapper, .map-search .map-container .left-side .filter-wrapper .filter-content {
    display: flex;
    flex-direction: column;
    gap: 20px;
}

