.map-search .map-container .right-side .marker .marker-box .marker-left-badge {
    position: absolute;
    top: -19px;
    left: -6.7px;
    width: 21px;
    height: 21px;
    background: var(--bg-color-01-light);
    border-radius: 8px;
    outline-offset: -1px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 2px 5px 0px 5px;
}

.map-search .map-container .right-side .marker .marker-box .marker-left-badge .text {
    width: 16px;
    height: 16px;
    font-size: 11px;
    font-weight: 600;
    text-align: center;
}

.map-search .map-container .right-side .marker.blue .marker-box .marker-left-badge {
    /*outline: 1px solid #066AEB;*/
    background: #066AEB;
}

.map-search .map-container .right-side .marker.blue .marker-box .marker-left-badge .text {
    color: #ffffff;
}

.map-search .map-container .right-side .marker.pink .marker-box .marker-left-badge {
    background: #DE37A5;
}

.map-search .map-container .right-side .marker.pink .marker-box .marker-left-badge .text {
    color: #ffffff;
}

.map-search .map-container .right-side .marker.orange .marker-box .marker-left-badge {
    background: #FFB03B;
}

.map-search .map-container .right-side .marker.orange .marker-box .marker-left-badge .text {
    color: #ffffff;
}

.map-search .map-container .right-side .map-overlay-range-1 {
    position: absolute;
    top: 149px;
    left: 511px;
    z-index: var(--z-index-map-overlay);
}

.map-search .map-container .right-side .map-overlay-range-2 {
    position: absolute;
    top: 287px;
    left: 581px;
    z-index: var(--z-index-map-overlay);
}

.map-search .map-container .right-side .map-overlay-range-3 {
    position: absolute;
    top: 352px;
    left: 750px;
    z-index: var(--z-index-map-overlay);
}

.map-search .map-container .right-side .map-overlay-range-4 {
    position: absolute;
    top: 600px;
    left: 780px;
    z-index: var(--z-index-map-overlay);
}

.map-search .map-container .right-side .distance-picker {
    padding: 1px 4px;
    background-color: var(--bg-color-01-light);
    border-radius: 2px;
    outline: 1px solid #DB3A1E;
    outline-offset: -1px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.map-search .map-container .right-side .distance-picker .text {
    color: #DB3A1E;
    font-size: 10px;
    font-weight: 500;
    word-wrap: break-word;
}

.map-search .map-container .right-side .total-distance-popup {
    display: flex;
    align-items: center;
    padding: 8px 8px 8px 13px;
    background-color: var(--bg-color-01-light);
    box-shadow: 0 8px 22px -6px rgba(0, 0, 0, 0.30);
    border: 1px solid color-mix(in srgb, #DB3A1E 35%, transparent);
    border-left: 4px solid #DB3A1E;
    border-radius: 10px;
    gap: 10px;
    font-size: 10px;
    font-weight: 600;
}

.map-search .map-container .right-side .total-distance-popup .content {
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.map-search .map-container .right-side .total-distance-popup .content .text-wrapper {
    display: flex;
    align-items: baseline;
    justify-content: flex-end;
    gap: 5px;
}

.map-search .map-container .right-side .total-distance-popup .content .text-wrapper .text-1 {
    color: var(--text-color-28);
    word-break: keep-all;
    font-size: 12px;
    font-weight: 600;
}

.map-search .map-container .right-side .total-distance-popup .content .text-wrapper .text-2 {
    color: #DB3A1E;
    font-size: 18px;
    font-weight: 800;
    line-height: 1;
    letter-spacing: -0.3px;
}

.map-search .map-container .right-side .total-distance-popup .icon-x {
    width: 22px;
    height: 22px;
    background-size: 13px;
    background-repeat: no-repeat;
    background-position: center;
    background-image: var(--icon-x);
    border-radius: 50%;
    cursor: pointer;
    opacity: 0.55;
    flex-shrink: 0;
    transition: opacity .15s ease, background-color .15s ease;
}

.map-search .map-container .right-side .total-distance-popup .icon-x:hover {
    opacity: 1;
    background-color: color-mix(in srgb, #DB3A1E 12%, transparent);
