main.edu-data .main-wrap .page-wrap {
    gap: 20px;
}

main.edu-data [class^=".button-wrapper-"] {
    padding-left: 5px;
}

main.edu-data .card-container {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: center;
}

main.edu-data .content-counts {
    width: 100%;
    padding-left: 9px;
    display: flex;
    font-size: 14px;
    font-style: normal;
    font-weight: 600;
    line-height: 0.95;
}

main.edu-data .content-counts .count {
    color: var(--text-color-16-light);
}

main.edu-data .content-counts .txt {
    color: var(--text-color-28-light);
}

main.edu-data .card-container .card-row {
    display: flex;
    align-items: flex-start;
    justify-content: flex-start;
    gap: 10px;
    flex-wrap: wrap;
}

main.edu-data .card-container .card {
    cursor: pointer;
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 10px;
    margin-top: 23px;
}

main.edu-data .card-container .card figure .image-mask {
    width: 238px;
    height: 239px;
    aspect-ratio: 238 / 239;
    border-radius: 10px;
    overflow: hidden;
    position: relative;
}

main.edu-data .card-container .card figure figcaption {
    display: flex;
    align-items: flex-start;
    width: 238px;
    height: 36px;
    overflow: hidden;
    margin-top: 10px;
    color: var(--text-color-01-light);
    font-size: 16px;
    font-style: normal;
    font-weight: 600;
    line-height: normal;
}

main.edu-data figure .image-mask img, main.edu-data .image-mask .fallback-bg {
    width: 100%;
