main.edu-data .detail-container {
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: 20px;
}

main.edu-data .detail-container > .info {
    padding: 10px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
}

main.edu-data .detail-container .info .left-side {
    width: 362px;
}

main.edu-data .detail-container .image-mask {
    width: 362px;
    aspect-ratio: 1 / 1;
}

main.edu-data .detail-container .info .right-side {
    padding: 10px;
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

main.edu-data .detail-container .info .right-side .title {
    color: var(--text-color-01);
    font-size: 27px;
    font-style: normal;
    font-weight: 600;
    line-height: normal;
}

main.edu-data .detail-container .info .right-side .table th, main.edu-data .detail-container .info .right-side .table td {
    font-size: 15px;
    height: 59px;
    font-size: 15px;
    font-style: normal;
    line-height: 1.866666666666667;
}

main.edu-data .detail-container .info .right-side .table th {
    width: 92px;
    color: var(--text-color-12);
    font-weight: 600;
}

main.edu-data .detail-container .info .right-side .table td {
    color: var(--text-color-28);
    font-weight: 500;
}

main.edu-data .detail-container .info .right-side .table td.price {
    color: #FF4D00;
    font-weight: 600;
}

main.edu-data .detail-container .info .right-side .bottom {
    display: block;
    text-align: center;
    padding: 10px 0;
}

main.edu-data .detail-container .info .right-side .bottom button {
    width: 263px;
}

main.edu-data .detail-container .tab-detail {
    border-bottom: 1px solid #E7E7E7;
    padding: 0 10px 10px 10px;
    min-height: 64px;
}

main.edu-data .detail-container .tab-detail .detail {
    max-width: calc(1064px - 20px);
}

main.edu-data .detail-container .back-list {
    width: 100%;
    display: flex;
    justify-content: center;
}

main.edu-data .detail-container .back-list .basic-3 {
    width: 263px;
    text-align: center;
    font-size: 16px;
    font-style: normal;
    font-weight: 500;
    line-height: 1;
