.tabs-container {
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.tabs-container .tabs-lists {
    margin-top: 20px;
    border: 1px solid #ACB2BC;
    padding: 30px 20px;
    border-radius: 8px;
}

.tabs-container .tabs-lists ul {
    display: flex;
    flex-direction: column;
    gap: 20px;
}

.tabs-container .tabs-lists li {
    display: flex;
    align-items: center;
}

.tabs-container .tabs-lists .icon.icon-map {
    display: block;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    width: 18px;
    height: 18px;
    background-image: var(--icon-map);
    margin-right: 8px;
}

.tabs-container .tabs-lists .court {
    color: var(--text-color-01);
    font-size: 17px;
    font-style: normal;
    font-weight: 500;
    line-height: normal;
}

.tabs-container .tabs-lists .area {
    color: var(--text-color-11);
    font-size: 17px;
    font-style: normal;
    font-weight: 400;
    line-height: normal;
    margin-left: 2px;
}

main.edu-data .court-container {
    margin-top: 10px;
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: 20px;
}

main.edu-data .court-container .court-title {
    color: var(--text-color-01);
    font-size: 21px;
    font-style: normal;
    font-weight: 600;
    line-height: normal;
}

main.edu-data .court-container .court-map {
    width: 100%;
    height: 443px;
}

main.edu-data .court-container .table th, main.edu-data .court-container .table td {
    font-size: 15px;
    height: 59px;
    font-size: 14px;
    font-style: normal;
    line-height: 1.86;
}

main.edu-data .court-container .table th {
    width: 148px;
    color: var(--text-color-12);
    font-weight: 600;
}

main.edu-data .court-container .table td {
    color: var(--text-color-28);
    font-weight: 500;
