main.edu-data .auction-tabs-container {
    width: 100%;
}

main.edu-data .auction-tabs-container .button-wrapper {
    margin-top: 30px;
    margin-bottom: 50px;
    display: flex;
    gap: 4px;
}

main.edu-data .auction-tabs-container .content-counts {
    padding-left: 0;
}

main.edu-data .auction-tabs-container .table-overline {
    display: block;
    width: 100%;
    margin-bottom: 0;
    margin-top: 20px;
    border: 1px solid var(--border-color-56);
}

main.edu-data .auction-tabs-container .table {
    width: 100%;
    table-layout: fixed;
    font-size: 14px;
    font-style: normal;
    line-height: 2;
}

main.edu-data .auction-tabs-container .table thead th {
    color: var(--text-color-12);
    font-weight: 600;
    height: 49px;
}

main.edu-data .auction-tabs-container .table thead th:nth-child(1) {
    width: 87px;
}

main.edu-data .auction-tabs-container .table thead th:nth-child(2) {
    width: auto;
}

main.edu-data .auction-tabs-container .table thead th:nth-child(3) {
    width: 148px;
}

main.edu-data .auction-tabs-container .table tbody td {
    text-align: center;
    color: var(--text-color-28);
    font-weight: 500;
    height: 49px;
}

main.edu-data .auction-tabs-container .table tbody td:nth-child(2) {
