main.edu-data .bid-container {
    width: 100%;
    display: flex;
    gap: 10px;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    margin-top: 10px;
}

main.edu-data .bid-container .accordion-item {
    width: 800px;
}

main.edu-data .bid-container .accordion-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
    padding: 20px 10px 20px 0px;
    border-bottom: 1px solid #EDEDED;
    gap: 5px;
    color: var(--text-color-01);
    font-size: 18px;
    font-style: normal;
    font-weight: 600;
    line-height: 1.20;
}

main.edu-data .bid-container .accordion-content {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease, padding 0.3s ease;
    background-color: #fff;
    padding: 0 16px;
}

main.edu-data .bid-container .accordion-content img {
    max-width: 800px;
}

main.edu-data .bid-container .accordion-item.active .accordion-content {
    padding: 16px;
}

main.edu-data .bid-container .arrow-up::before {
