main.support .notice-container {
    width: 100%;
    display: flex;
    gap: 10px;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    margin-top: 10px;
}

main.support .notice-container .notice-item {
    width: 100%;
    display: flex;
    flex-direction: column;
    cursor: pointer;
    padding: 18px 0px;
    border-bottom: 1px solid var(--border-color-02);
    gap: 5px;
}

main.support .notice-container .notice-item.not-pointer {
    cursor: default;
}

main.support .notice-container .notice-item .notice-header {
    width: 100%;
    color: var(--text-color-01);
    font-size: 16px;
    font-style: normal;
    font-weight: 500;
    line-height: 1.40;
}

main.support .notice-container .notice-item .notice-header h4 {
    font-weight: 500;
}

main.support .notice-container .notice-item .notice-content {
    display: flex;
    gap: 14px;
    font-weight: 200;
    font-size: 15px;
    color: #929294;
}

main.support .notice-container .notice-item .notice-content .type {
    font-weight: 400;
    color: #458DD6;
}

main.support .notice-container .notice-detail {
    width: 100%;
    padding: 20px 0;
    border-bottom: 1px solid #EDEDED;
}

main.support .notice-container .notice-detail .txt {
    color: var(--text-color-02);
    font-size: 15px;
    font-style: normal;
    font-weight: 600;
    line-height: 1.45;
    white-space: pre-wrap;
}

main.support .notice-container .back-list {
    padding-top: 30px;
    width: 100%;
    display: flex;
    justify-content: center;
}

main.support .notice-container .back-list .basic-3 {
    width: 263px;
    text-align: center;
    font-size: 16px;
    font-style: normal;
    font-weight: 500;
    line-height: 1;
