main.support .faq-container {
    width: 100%;
    display: flex;
    gap: 10px;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    margin-top: 10px;
}

main.support .faq-container .button-wrapper-1, main.support .faq-container .accordion-item {
    width: 100%;
}

main.support .faq-container .button-wrapper-1 button.button {
    padding: 11px 14px;
    height: 36px;
    border-radius: 16px;
    font-size: 15px;
    font-weight: 500;
    box-sizing: border-box;
}

main.support .faq-container .accordion-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
    padding: 20px 10px 20px 0px;
    border-bottom: 1px solid var(--border-color-02);
    gap: 5px;
    line-height: 1.553571428571429;
}

main.support .faq-container .accordion-header .left-side {
    display: flex;
    flex-direction: column;
    gap: 5px;
}

main.support .faq-container .accordion-header .left-side .title {
    color: var(--text-color-01);
    font-size: 18px;
    font-style: normal;
    font-weight: 600;
}

main.support .faq-container .accordion-header .left-side .tags {
    display: flex;
    gap: 5px;
    color: #458DD6;
    font-size: 15px;
    font-style: normal;
    font-weight: 400;
}

main.support .faq-container .accordion-content {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease, padding 0.3s ease;
    background-color: var(--bg-color-02);
    padding: 0 16px;
    color: var(--text-color-11);
    font-size: 17px;
    font-weight: 500;
    line-height: 1.279411764705882;
}

main.support .faq-container .accordion-item.active .accordion-content {
    padding: 20px;
}

main.support .faq-container .arrow-up::before {
    content: "";
    background-image: var(--icon-angle-down);
    display: inline-block;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    width: 24px;
    height: 24px;
    transition: transform 0.3s ease;
}

main.support .faq-container .accordion-item.active .arrow-up::before {
    transform: rotate(180deg);
