main.item-detail {
    padding: 0;
    height: 100vh;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

main.item-detail .header {
    border-bottom: 1px solid var(--border-color-10);
}

main.item-detail .header .header-box {
    width: 1200px;
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: flex-start;
    height: 45px;
    padding: 0 15px;
    margin: 0 auto;
    gap: 16px;
}

main.item-detail .header .header-box .left-side .logo a {
    cursor: pointer;
    text-decoration: none;
    display: flex;
    align-items: center;
    justify-content: flex-start;
    gap: 4px;
    color: var(--text-color-01);
    text-align: center;
    font-size: 1.9rem;
    font-style: normal;
    font-weight: 800;
    line-height: 1.068421052631579;
}

main.item-detail .header .header-box .icon-logo {
    display: block;
    width: 130px;
    height: 21px;
    background-size: contain;
