main.item-detail .header .header-box .right-side {
    display: flex;
    align-items: center;
    gap: 10px;
}

main.item-detail .header .header-box .right-side p {
    font-size: 1.3rem;
    font-weight: 700;
    color: var(--text-color-24)
}

main.item-detail .header .header-box .right-side p span {
