main.item-detail .main-wrap > .page-wrap ::-webkit-scrollbar-button {
    display: none;
}

main.item-detail .main-wrap > .page-wrap ::-webkit-scrollbar-thumb {
    background: rgba(134, 151, 178, 0.5);
    border-radius: 3.5px;
}

main.item-detail .main-wrap > .page-wrap ::-webkit-scrollbar-track {
