main.item-detail-extra {
    width: 100%;
    min-width: 700px;
    padding: 0 !important;
}

main.item-detail-extra .header {
    /*border-bottom: 1px solid var(--border-color-10);*/
}

main.item-detail-extra .header .title {
    display: flex;
    align-items: center;
    justify-content: start;
    color: #ffffff;
    font-size: 15px;
    font-weight: 400;
    background: #262D39;
    padding: 10px 10px;
    height: 46px;
}

main.item-detail-extra .header .title .cs-nm {
    font-weight: 400;
}

main.item-detail-extra .header .title .addr {
    display: inline-block;
    font-weight: 100;
}

main.item-detail-extra .header .header-box {
    width: 100%;
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    height: 45px;
    padding: 0;
    margin: 0 auto;
}

main.item-detail-extra .header .header-box .left-side .logo a {
    cursor: pointer;
    text-decoration: none;
    display: flex;
    align-items: center;
    justify-content: flex-start;
    gap: 4px;
    color: var(--text-color-01);
    text-align: center;
    font-size: 19px;
    font-style: normal;
    font-weight: 800;
    line-height: 1.068421052631579;
}

main.item-detail-extra .header .header-box .icon-logo {
    display: block;
    width: 130px;
    height: 21px;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    background-image: var(--icon-logo);
}

main.item-detail-extra .container {
    display: flex;
    flex-direction: column;
    width: 100%;
    height: calc(100vh - 100px);
    overflow: auto;
