main.item-analysis {
    padding: 0;
}

main.item-analysis .main-wrap {
    width: 1000px;
    padding: 0;
    margin-bottom: 0;
}

main.item-analysis .main-wrap .page-wrap {
    display: flex;
    flex-direction: row;
    align-items: flex-start;
    justify-content: space-between;
    padding: 10px;
    gap: 15px;
}

main.item-analysis .main-wrap > .page-wrap > .left-side {
    width: 100%;
}

main.item-analysis .main-wrap .page-wrap .left-side .detail-container {
    display: flex;
    flex-direction: column;
    gap: 20px;
}

main.item-analysis .main-wrap .page-wrap .left-side .title {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
    margin-top: 17px;
}

main.item-analysis .main-wrap .page-wrap .left-side .title .item-name {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
}

main.item-analysis .main-wrap .page-wrap .left-side .title .item-name span.black {
    color: var(--text-color-23);
    font-size: 25px;
    font-weight: 500;
}

main.item-analysis .main-wrap .page-wrap .left-side .title .item-name span.blue {
    color: var(--text-color-212);
    font-size: 25px;
    font-weight: 700;
}

main.item-analysis .main-wrap .page-wrap .left-side .title .item-number {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    margin-bottom: 17px;
}

main.item-analysis .main-wrap .page-wrap .left-side .title .item-number span {
    color: #6E6E6E;
    font-size: 15px;
    font-weight: 500;
}

main.item-analysis .main-wrap .page-wrap .left-side .title .item-number .button {
    width: 26px;
    height: 24px;
    padding: 0 8px;
    border-radius: 5px;
    font-size: 15px;
    border: none;
    cursor: pointer;
}

main.item-analysis .main-wrap .page-wrap .left-side .title .item-number button.button.basic-1 {
    background-color: var(--text-color-212);
    color: white;
}

main.item-analysis .main-wrap .page-wrap .left-side .title .item-number button.button.basic-3 {
    background-color: #E2E2E2;
    color: black;
}

main.item-analysis .main-wrap .page-wrap .left-side .title .item-guide {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
}

main.item-analysis .main-wrap .page-wrap .left-side .title .item-guide .sale-date, main.item-analysis .main-wrap .page-wrap .left-side .subtitle .sale-date {
    font-size: 14px;
    font-weight: 400;
    color: var(--text-color-11);
}

main.item-analysis .main-wrap .page-wrap .left-side .title .item-guide .sale-date span.date {
    color: var(--text-color-01);
}

main.item-analysis .main-wrap .page-wrap .left-side .title .item-guide .sale-date span.before-bid-number, main.item-analysis .main-wrap .page-wrap .left-side .subtitle .sale-date span.before-bid-number {
    font-weight: 600;
    color: var(--text-color-212);
}

main.item-analysis .main-wrap .page-wrap .left-side .title .item-guide .sale-date span.phone-number {
    color: var(--text-color-01);
    text-decoration-line: underline;
    text-decoration-style: solid;
}

main.item-analysis .main-wrap .page-wrap .left-side .title .item-guide .button-wrapper {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 10px;
}

main.item-analysis .main-wrap .page-wrap .left-side hr.divider {
    border: none;
    border-top: 1px solid var(--border-color-10);
    margin: 1px 0;
}

main.item-analysis .main-wrap .page-wrap .left-side table.table th {
    color: var(--text-color-53);
    font-size: 14px;
    font-weight: 600;
    padding: 13px 10px;
}

main.item-analysis .main-wrap .page-wrap .left-side table.table td {
    color: var(--text-color-01);
    font-size: 15px;
    font-weight: 400;
    padding: 13px 10px;
}

main.item-analysis .main-wrap .page-wrap .left-side table.table.main-table {
    margin-bottom: 20px;
}

main.item-analysis .main-wrap .page-wrap .left-side table.table.main-table th {
    width: 83.5px;
    height: 47px;
}

main.item-analysis .main-wrap .page-wrap .left-side table.table.main-table th.location {
    height: 80px;
}

main.item-analysis .main-wrap .page-wrap .left-side table.table.main-table th.special-note {
    height: 106px;
    vertical-align: top;
}

main.item-analysis .main-wrap .page-wrap .left-side table.table.main-table td {
    width: 199px;
}

main.item-analysis .main-wrap .page-wrap .left-side table.table.main-table td span {
    color: var(--text-color-11);
}

main.item-analysis .main-wrap .page-wrap .left-side table.table.main-table td.bold {
    font-weight: 500;
}

main.item-analysis .main-wrap .page-wrap .left-side table.table.main-table td.blue {
    color: var(--text-color-212);
}

main.item-analysis .main-wrap .page-wrap .left-side table.table.main-table td.image-section {
    width: 389px;
    padding: 0px;
}

main.item-analysis .main-wrap .page-wrap .left-side table.table.main-table td.special-note {
    vertical-align: top;
}

main.item-analysis .main-wrap .page-wrap .left-side table.table.main-table td .td-wrapper.location {
