main.grade-benefits .page-wrap .grade-top .right-side progress {
    appearance: none;
    width: 100%;
}

main.grade-benefits .page-wrap .grade-top .right-side progress::-webkit-progress-bar {
    background: #E5E5E5;
    border-radius: 12px;
    border: none;
    height: 7px;
    width: 100%;
    overflow: hidden;
}

main.grade-benefits .page-wrap .grade-top .right-side progress::-webkit-progress-value {
    background: var(--text-color-57);
    border-radius: 0px;
    height: 7px;
}

main.grade-benefits .page-wrap .grade-bottom {
    width: 100%;
}

main.grade-benefits .page-wrap .grade-bottom h5 {
    color: #959595;
    font-size: 18px;
    font-style: normal;
    font-weight: 600;
    line-height: 1.33333;
    margin-top: 50px;
}

main.grade-benefits .page-wrap .grade-bottom .table-overline {
    display: block;
    width: 100%;
    margin-bottom: 0;
    margin-top: 10px;
    border: 0 none;
}

main.grade-benefits .page-wrap .grade-bottom .table {
    text-align: center;
    vertical-align: middle;
    margin-bottom: 65px;
    table-layout: fixed;
    width: 100%;
}

main.grade-benefits .page-wrap .grade-bottom .table thead th img {
    width: 70px;
    height: 70px;
}

main.grade-benefits .page-wrap .grade-bottom .table thead th {
    color: #595959;
    font-size: 17px;
    font-style: normal;
    font-weight: 600;
    line-height: 1.64;
    background-color: transparent;
}

main.grade-benefits .page-wrap .grade-bottom .table tbody th {
    color: var(--text-color-52);
    text-align: center;
    font-size: 14px;
    font-style: normal;
    font-weight: 600;
    line-height: 2;
    width: 148px;
}

main.grade-benefits .page-wrap .grade-bottom .table tbody th .small {
    color: var(--text-color-02);
    font-size: 13px;
    font-style: normal;
    font-weight: 500;
    line-height: 1.76;
}

main.grade-benefits .page-wrap .grade-bottom .table tbody td {
    color: #868686;
    text-align: center;
    font-size: 14px;
    font-style: normal;
    font-weight: 400;
    line-height: 2;
}

main.grade-benefits .page-wrap .grade-bottom .table thead th.active, main.grade-benefits .page-wrap .grade-bottom .table tbody td.active {
    color: var(--text-color-57);
}

main.note {
    padding: 0;
    margin: 0;
}
